int ternary_search_max(int l, int r) {
	// 范围 [l, r]
	while (l < r) {
		int mid = (l + r) / 2;
		if (f(mid) < f(mid + 1)) {
			l = mid + 1;
		}
		else {
			r = mid;
		}
	}
	return l; // 最大值点，最大值 f(l)
}

double ternary_search_max(double l, double r) {
	// 范围 [l, r]，f 单峰，f 返回 double
	for (int i = 0; i < 100; ++i) {
		double mid = (l + r) / 2;
		double step = (r - l) * 1e-4;      // 相邻点间距，随区间缩放
		if (f(mid) < f(mid + step)) {      // 右高 → 峰在右边
			l = mid;
		} else {                           // 左高或相等 → 峰在左边
			r = mid;
		}
	}
	return (l + r) / 2;                    // 最大值点，最大值 f(返回值)
}
